import random, statistics

def ab_test({{variants}}, {{examples}}, {{score_fn}}):
    results = {k: [] for k in {{variants}}}
    for ex in {{examples}}:
        for name, prompt_fn in {{variants}}.items():
            results[name].append({{score_fn}}(prompt_fn(ex), ex))
    return {k: statistics.mean(v) for k, v in results.items()}
